-- Instrument semantic cases from LIB-4A's shared synthetic conformance corpus.
-- PostgREST/jsonb normalizes duplicate keys; these two cases intentionally demonstrate that limit.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.envelope(p_measurement jsonb)
returns jsonb language sql immutable as $$
    select jsonb_build_object('schema_version','gsip-library-intake-v1',
        'intake_id','00000000-0000-0000-0000-000000000001',
        'node_id','00000000-0000-0000-0000-000000000002',
        'sample_id','00000000-0000-0000-0000-000000000003',
        'submission_id','00000000-0000-0000-0000-000000000004',
        'protocol_version','gsip-capture-v1',
        'context',jsonb_build_object('depth_top_cm',0,'depth_bottom_cm',20,'condition','unknown'),
        'instrument_declaration',jsonb_build_object('measurement_id',
            '00000000-0000-0000-0000-000000000005','measurement',p_measurement));
$$;
select lives_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))','valid instrument: three-band-fictional');
select lives_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[200.0,450.0,25000.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))','valid instrument: wavelength-endpoints');
select lives_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.0,0.5,1.0],"uncertainty":[0.0,0.5,1.0]}''::jsonb))','valid instrument: fraction-endpoints');
select lives_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"ABCDEFAB-CDEF-ABCD-EFAB-CDEFABCDEFAB","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))','valid instrument: uppercase-uuid');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01],"private_note":"fictional-only"}''::jsonb))',null,null,'invalid instrument: unknown-field');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"camera_rgb","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: unsupported-measurement-kind');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: upper-case-digest');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: short-digest');
