select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: unaligned-reflectance');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[0.3,0.4,0.5],"uncertainty":[0.01,0.01]}''::jsonb))',null,null,'invalid instrument: unaligned-uncertainty');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[30.0,40.0,50.0],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: percent-reflectance');
select throws_ok('select private.validate_library_request(pg_temp.envelope(''{"kind":"instrument_reflectance","source_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","instrument_id":"00000000-0000-0000-0000-000000000006","calibration_id":"00000000-0000-0000-0000-000000000007","wavelength_nm":[450.0,550.0,650.0],"reflectance":[-0.1,0.4,0.5],"uncertainty":[0.01,0.01,0.01]}''::jsonb))',null,null,'invalid instrument: negative-reflectance');
