create function pg_temp.banded(p_count integer)
returns jsonb language sql immutable as $$
    select jsonb_build_object('kind','instrument_reflectance','source_sha256',repeat('a',64),
        'instrument_id','00000000-0000-0000-0000-000000000001',
        'calibration_id','00000000-0000-0000-0000-000000000002',
        'wavelength_nm',(select jsonb_agg(200+(i-1)*(24800::numeric/(greatest(p_count-1,1)))) from generate_series(1,p_count)i),
        'reflectance',(select jsonb_agg(0.2) from generate_series(1,p_count)),
        'uncertainty',(select jsonb_agg(0.01) from generate_series(1,p_count)));
$$;
select throws_ok('select private.validate_library_request(pg_temp.envelope(pg_temp.banded(2)))','22023',null,'refused band count 2');
select lives_ok('select private.validate_library_request(pg_temp.envelope(pg_temp.banded(3)))','admitted band count 3');
select lives_ok('select private.validate_library_request(pg_temp.envelope(pg_temp.banded(10000)))','admitted band count 10000');
select throws_ok('select private.validate_library_request(pg_temp.envelope(pg_temp.banded(10001)))','22023',null,'refused band count 10001');
select * from finish();
rollback;
